import requests
lat, lng, radius = 12.7165196, 78.2102820, 25
for taxon_id, label in [(1324791,'Janalychas'), (432766,'Phrynichus'), (1287978,'Gigantometrus swammerdami'), (1598326,'Hypoctoninae'), (199488,'Pandercetes'), (420707,'Gnathopalystes'), (171422,'Herennia multipuncta'), (158342,'Poltys')]:
    params={'lat':lat,'lng':lng,'radius':radius,'taxon_id':taxon_id,'verifiable':'true','per_page':3,'order_by':'observed_on','order':'desc'}
    js=requests.get('https://api.inaturalist.org/v1/observations', params=params).json()
    print('\n##', label, 'total=', js.get('total_results'))
    for obs in js.get('results',[])[:3]:
        print(obs.get('id'), obs.get('species_guess'), obs.get('observed_on'), obs.get('location'), obs.get('uri'))
