import requests
lat, lng, radius = 12.7165196, 78.2102820, 10
params={'lat':lat,'lng':lng,'radius':radius,'taxon_id':47118,'verifiable':'true','per_page':50}
r=requests.get('https://api.inaturalist.org/v1/observations/species_counts', params=params).json()
for name in ['Argiope','Olios','Oxyopes','Poltys','Herennia multipuncta','Lycosa','Scytodidae','Gnaphosidae']:
    for item in r['results']:
        t=item['taxon']
        if t['name']==name or t.get('preferred_common_name')==name:
            print(item['count'], t['id'], t['name'], '|', t.get('preferred_common_name'))
